import { defineConfig, devices } from '@playwright/test'
import { readFileSync } from 'fs'
import { resolve } from 'path'

/**
 * @see https://playwright.dev/docs/test-configuration
 */

// Load environment variables from .env.local if it exists
try {
  const envPath = resolve(process.cwd(), '.env.local')
  const envContent = readFileSync(envPath, 'utf-8')
  envContent.split('\n').forEach(line => {
    const trimmed = line.trim()
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=')
      if (key && valueParts.length > 0) {
        process.env[key] = valueParts.join('=')
      }
    }
  })
} catch (error) {
  // .env.local doesn't exist or can't be read, continue without it
}

// Check if we have authentication credentials available
const hasSupabaseCredentials = !!(process.env.VITE_SUPABASE_URL && process.env.VITE_SUPABASE_ANON_KEY)

export default defineConfig({
  testDir: './tests/e2e',
  /* Run tests in files in parallel */
  fullyParallel: true,
  /* Fail the build on CI if you accidentally left test.only in the source code. */
  forbidOnly: !!process.env.CI,
  /* Retry on CI only */
  retries: process.env.CI ? 2 : 0,
  /* Opt out of parallel tests on CI. */
  workers: process.env.CI ? 1 : undefined,
  /* Reporter to use. See https://playwright.dev/docs/test-reporters */
  reporter: 'html',
  /* Shared settings for all the projects below. See https://playwright.dev/docs/api/class-testoptions. */
  use: {
    /* Base URL to use in actions like `await page.goto('/')`. */
    baseURL: 'http://localhost:5176',
    /* Collect trace when retrying the failed test. See https://playwright.dev/docs/trace-viewer */
    trace: 'on-first-retry',
    /* Set global timeout for actions like waitForSelector to 5 seconds */
    actionTimeout: 5000,
  },

  /* Configure projects for major browsers */
  projects: [
    // Setup project - only run if we have Supabase credentials
    ...(hasSupabaseCredentials 
      ? [{ name: 'setup', testMatch: /setup\/.*\.setup\.ts/ }]
      : []
    ),

    // Smoke tests - always run these (no authentication required)
    {
      name: 'chromium-smoke',
      use: { ...devices['Desktop Chrome'] },
      testMatch: /smoke\/.*\.spec\.ts/,
    },

    // Authenticated tests - only run if we have Supabase credentials
    ...(hasSupabaseCredentials ? [
      {
        name: 'chromium-pages',
        use: { 
          ...devices['Desktop Chrome'],
          storageState: 'tests/.auth/user.json',
        },
        dependencies: ['setup'],
        testMatch: /pages\/.*\.spec\.ts/,
      },
      {
        name: 'chromium-components',
        use: { 
          ...devices['Desktop Chrome'],
          storageState: 'tests/.auth/user.json',
        },
        dependencies: ['setup'],
        testMatch: /components\/.*\.spec\.ts/,
      },
      {
        name: 'chromium-flows',
        use: { 
          ...devices['Desktop Chrome'],
          storageState: 'tests/.auth/user.json',
        },
        dependencies: ['setup'],
        testMatch: /flows\/.*\.spec\.ts/,
      },
      {
        name: 'chromium-navigation',
        use: { 
          ...devices['Desktop Chrome'],
          storageState: 'tests/.auth/user.json',
        },
        dependencies: ['setup'],
        testMatch: /navigation\/.*\.spec\.ts/,
      }
    ] : []),

    // Additional browsers - only run locally and only for smoke tests in CI
    ...(process.env.CI ? [
      // In CI, only run smoke tests on additional browsers
      {
        name: 'firefox-smoke',
        use: { ...devices['Desktop Firefox'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },
    ] : [
      // Local development - run all browsers for smoke tests
      {
        name: 'firefox-smoke',
        use: { ...devices['Desktop Firefox'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },
      {
        name: 'webkit-smoke',
        use: { ...devices['Desktop Safari'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },
      {
        name: 'mobile-chrome-smoke',
        use: { ...devices['Pixel 5'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },
      {
        name: 'mobile-safari-smoke',
        use: { ...devices['iPhone 12'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },

      // Local authenticated tests on additional browsers (if credentials available)
      ...(hasSupabaseCredentials ? [
        {
          name: 'firefox-pages',
          use: { 
            ...devices['Desktop Firefox'],
            storageState: 'tests/.auth/user.json',
          },
          dependencies: ['setup'],
          testMatch: /pages\/.*\.spec\.ts/,
        },
        {
          name: 'webkit-pages',
          use: { 
            ...devices['Desktop Safari'],
            storageState: 'tests/.auth/user.json',
          },
          dependencies: ['setup'],
          testMatch: /pages\/.*\.spec\.ts/,
        },
      ] : [])
    ]),

    /* Test against branded browsers. */
    // {
    //   name: 'Microsoft Edge',
    //   use: { ...devices['Desktop Edge'], channel: 'msedge' },
    // },
    // {
    //   name: 'Google Chrome',
    //   use: { ...devices['Desktop Chrome'], channel: 'chrome' },
    // },
  ],

  /* Run your local dev server before starting the tests */
  webServer: {
    command: 'npm run dev -- --port 5176',
    url: 'http://localhost:5176',
    reuseExistingServer: !process.env.CI,
    timeout: 10 * 1000, // 10 seconds timeout for server startup
  },
})

