// Helper function to open the gear form
async function openGearForm(page) {
  // Look for the floating action button specifically (uses fixed positioning)
  // It should be at the bottom-right of the screen
  const floatingButton = page.locator('button[class*="fixed"][class*="bottom"][class*="right"]').first()

  // If not found by position classes, try by aria-label or other attributes
  let button = floatingButton
  if (await button.count() === 0) {
    button = page.locator('button[aria-label*="Add"], button[aria-label*="add"], button[aria-label*="New"], button[aria-label*="new"]').first()
  }

  // Last resort - find any button with a plus icon
  if (await button.count() === 0) {
    button = page.locator('button').filter({ has: page.locator('svg path[d*="M12 5v14M5 12h14"], svg path[d*="M12 4v16M4 12h16"]') }).first()
  }

  if (await button.count() === 0 || !await button.isVisible()) {
    test.skip('Floating action button (add gear) not found')
  }

  // Use force click to bypass any overlapping elements
  await button.click({ force: true })
  await page.waitForTimeout(500) // Give form time to appear

