    }

    // Navigate to gear page where the form is used
    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')
    await page.waitForSelector('main, [role="main"]', { timeout: 10000 })

    // Ensure we're authenticated (not redirected to login)
    if (page.url().includes('/login')) {
      throw new Error('Authentication failed - redirected to login page')
    }
  })

  // Helper function to open the gear form
  async function openGearForm(page) {
    // From debug output, we know there's a floating action button (round, empty text)
    // Look for the floating action button - likely bottom-right positioned
    const floatingButton = page.locator('button').filter({ hasText: '' }).filter({
      has: page.locator('svg, .lucide')
    }).first()

    if (await floatingButton.count() === 0 || !await floatingButton.isVisible()) {
      test.skip('Floating action button (add gear) not found')
    }

    await floatingButton.click()
    await page.waitForTimeout(1500) // Give form time to appear

    // After clicking, look for form/dialog/drawer that appeared
    const possibleForms = [
      page.locator('[role="dialog"]'),
      page.locator('.modal'),
      page.locator('[data-state="open"][role="dialog"]'), // More specific - only dialogs
      page.locator('form').filter({ hasText: /name|weight/i }),
      page.locator('div').filter({ hasText: /Add.*Gear|New.*Item/i }),
    ]

    let form = null
    for (const formSelector of possibleForms) {
      if (await formSelector.count() > 0 && await formSelector.isVisible()) {
        form = formSelector.first()
        break
      }
    }

