      const nameField = form.locator('input[name="name"], input[placeholder*="name" i], #name')
      const weightField = form.locator('input[name="weight"], input[placeholder*="weight" i], #weight')

      await expect(nameField.first()).toBeVisible()
      await expect(weightField.first()).toBeVisible()
