      const submitCount = await possibleSubmits.count()

      if (submitCount === 0) {
        test.skip('No buttons found in form')
      }

      // Try clicking the primary action button (likely last or most prominent)
      const submitButton = possibleSubmits.last()
      await submitButton.click()

      // After clicking submit, form should either:
      // 1. Stay open (validation failed)
      // 2. Show validation message
      // 3. Form should still be visible if validation prevented submission
      await page.waitForTimeout(1000)

      // Just verify that form interaction doesn't crash the app
      const body = page.locator('body')
      await expect(body).toBeVisible()
    })

    test('accepts valid form data', async ({ page }) => {
      const form = await openGearForm(page)

      // Fill in the first few input fields with reasonable data
      const inputs = form.locator('input')
      const inputCount = await inputs.count()

      if (inputCount >= 1) {
        await inputs.nth(0).fill('Test Item')
      }
      if (inputCount >= 2) {
        await inputs.nth(1).fill('150')
      }

      // Submit form
      const buttons = form.locator('button')
      if (await buttons.count() > 0) {
        await buttons.last().click()
      }

      // Just ensure the action completes without crashing
      await page.waitForTimeout(1000)
      const body = page.locator('body')
      await expect(body).toBeVisible()
    })
  })

  test.describe('Responsive Behavior', () => {
    test('adapts to mobile viewport', async ({ page }) => {
      await page.setViewportSize({ width: 375, height: 667 })
      await page.reload()
      await page.waitForLoadState('domcontentloaded')

      const form = await openGearForm(page)

      // Form should still be usable on mobile
      await expect(form).toBeVisible()

      // Fields should be stacked vertically (not side by side)
      const nameField = form.locator('[name="name"], #name, input[placeholder*="name" i]').first()
      const weightField = form.locator('[name="weight"], #weight, input[placeholder*="weight" i]').first()

      const nameBox = await nameField.boundingBox()
      const weightBox = await weightField.boundingBox()

      if (nameBox && weightBox) {
        // On mobile, weight field should be below name field
        expect(weightBox.y).toBeGreaterThan(nameBox.y)
      }
    })

    test('utilizes desktop space', async ({ page }) => {
      await page.setViewportSize({ width: 1200, height: 800 })
      await page.reload()
      await page.waitForLoadState('domcontentloaded')

      const form = await openGearForm(page)

      // Form should be visible and well-laid-out
      await expect(form).toBeVisible()

      // Should have reasonable form width (not too narrow or too wide)
      const formBox = await form.boundingBox()
      if (formBox) {
        expect(formBox.width).toBeGreaterThan(300)
        expect(formBox.width).toBeLessThan(800)
      }
    })
  })
})

